# Reads from ../../privacy-security-manifest.yaml.
# Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
# Docs: docs/scaffolds/phi_redaction.md
#
# Healthcare-specific PHI redactor. Use whenever a clinical-data-bearing object
# might leak into a log, error stack, exception, or third-party error tracker.
#
# Beyond generic PII patterns, this redactor strips clinical free-text fields
# (notes, diagnosis, symptom descriptions) and structured clinical values.

from __future__ import annotations

import re
from collections.abc import Mapping
from typing import Any

from .audit_log import redact as base_redact
from .audit_log import to_plain

PHI_PLACEHOLDER = '[PHI_REDACTED]'

# Clinical field names commonly seen in EMR / EHR schemas.
CLINICAL_FIELD_NAMES = frozenset({
    'diagnosis', 'icd10', 'icd_10', 'snomed', 'snomed_ct',
    'prescription', 'medication', 'drug', 'dosage', 'rx',
    'lab_result', 'lab_results', 'lab_value', 'test_result',
    'vital_signs', 'bp', 'pulse', 'spo2', 'temperature', 'heart_rate',
    'symptom', 'symptoms', 'symptom_notes', 'chief_complaint',
    'treatment', 'treatment_plan', 'procedure',
    'allergy', 'allergies', 'medical_history',
    'note', 'notes', 'soap_note', 'physician_note',
    'encounter', 'encounter_summary',
})

# Free-text fields that often hide PHI within them.
FREE_TEXT_CLINICAL_HINTS = [
    re.compile(r'\bpatient (was|is|has)\b', re.IGNORECASE),
    re.compile(r'\bdiagnos(ed|is)\b', re.IGNORECASE),
    re.compile(r'\bprescrib(ed|ing)\b', re.IGNORECASE),
    re.compile(r'\bmg\b|\bml\b|\biu\b', re.IGNORECASE),
]


def _is_clinical_text(value: str) -> bool:
    return any(pattern.search(value) for pattern in FREE_TEXT_CLINICAL_HINTS)


class RedactedError(Exception):
    """A copy of an exception that is safe to log. `name` keeps the original class name."""

    def __init__(self, message: str, name: str) -> None:
        super().__init__(message)
        self.name = name


def _redact_exception(error: BaseException) -> RedactedError:
    copy = RedactedError(phi_redact(str(error)), type(error).__name__)
    if error.__cause__ is not None:
        copy.__cause__ = _redact_exception(error.__cause__)
    return copy


def phi_redact(value: Any) -> Any:
    """
    Redact PHI from any value before it enters a log / error / external sink.

    Use BEFORE:
      - raising an error (especially one routed to Sentry / Datadog)
      - logging via logging / print
      - serialising to a metric label
    """
    if value is None:
        return value

    if isinstance(value, BaseException):
        return _redact_exception(value)

    if isinstance(value, str):
        return PHI_PLACEHOLDER if _is_clinical_text(value) else base_redact(value)

    value = to_plain(value)

    if isinstance(value, (list, tuple, set, frozenset)):
        return [phi_redact(v) for v in value]

    if isinstance(value, Mapping):
        return {
            str(k): PHI_PLACEHOLDER if str(k).lower() in CLINICAL_FIELD_NAMES else phi_redact(v)
            for k, v in value.items()
        }

    return base_redact(value)


def redact_err(error: BaseException) -> RedactedError:
    """
    Convenience: wrap an exception so log/raise sites can stay terse.

      try:
          ...
      except Exception as e:
          logger.error('lookup failed: %s', redact_err(e))
          raise
    """
    return _redact_exception(error)
